def exterior(left, right, cache):
    key = (left, right)
    found = cache.get(key)
    if found is not None:
        return found
    sign = 1
    for x in left:
        for y in right:
            if x == y:
                cache[key] = ((), 0)
                return cache[key]
            if x > y:
                sign = -sign
    found = (tuple(sorted(left + right)), sign)
    cache[key] = found
    return found


def normalize(word, cache):
    polynomial = {((), ()): 1}
    for flag, mode in word:
        following = {}
        for blocks, coefficient in polynomial.items():
            creators, annihilators = blocks
            if flag:
                if mode in annihilators:
                    position = annihilators.index(mode)
                    key = (creators, annihilators[:position] + annihilators[position + 1:])
                    value = coefficient
                    if (len(annihilators) - position - 1) % 2:
                        value = -value
                    following[key] = following.get(key, 0) + value
                merged, sign = exterior(creators, (mode,), cache)
                if sign:
                    if len(annihilators) % 2:
                        sign = -sign
                    key = (merged, annihilators)
                    following[key] = following.get(key, 0) + coefficient * sign
            else:
                merged, sign = exterior(annihilators, (mode,), cache)
                if sign:
                    key = (creators, merged)
                    following[key] = following.get(key, 0) + coefficient * sign
        polynomial = {key: value for key, value in following.items() if value}
    return polynomial


def contractions(annihilators, creators, cache):
    key = (annihilators, creators)
    found = cache.get(key)
    if found is not None:
        return found
    states = [(annihilators, creators, 1)]
    for mode in annihilators:
        if mode in creators:
            additions = []
            for remaining_a, remaining_c, sign in states:
                position_a = remaining_a.index(mode)
                position_c = remaining_c.index(mode)
                if (len(remaining_a) - position_a - 1 + position_c) % 2:
                    sign = -sign
                additions.append((remaining_a[:position_a] + remaining_a[position_a + 1:], remaining_c[:position_c] + remaining_c[position_c + 1:], sign))
            states.extend(additions)
    found = []
    for remaining_a, remaining_c, sign in states:
        if (len(remaining_a) * len(remaining_c)) % 2:
            sign = -sign
        found.append((remaining_c, remaining_a, sign))
    cache[key] = found
    return found


def propose(payload):
    words = payload['words']
    merge_cache = {}
    contraction_cache = {}
    word_cache = {}
    polynomials = []
    adjoints = []
    for word in words:
        polynomial = word_cache.get(word)
        if polynomial is None:
            polynomial = normalize(word, merge_cache)
            word_cache[word] = polynomial
        terms = []
        adjoint_terms = []
        for blocks, coefficient in polynomial.items():
            creators, annihilators = blocks
            terms.append((creators, annihilators, coefficient))
            parity = len(creators) * (len(creators) - 1) // 2 + len(annihilators) * (len(annihilators) - 1) // 2
            if parity % 2:
                coefficient = -coefficient
            adjoint_terms.append((annihilators, creators, coefficient))
        polynomials.append(terms)
        adjoints.append(adjoint_terms)
    orbits = {}
    for i in range(len(words)):
        for j in range(i, len(words)):
            coordinate = (i, j)
            for left_c, left_a, left_value in adjoints[i]:
                for right_c, right_a, right_value in polynomials[j]:
                    scale = left_value * right_value
                    middle = contractions(left_a, right_c, contraction_cache)
                    for middle_c, middle_a, middle_sign in middle:
                        creators, creator_sign = exterior(left_c, middle_c, merge_cache)
                        if creator_sign:
                            annihilators, annihilator_sign = exterior(middle_a, right_a, merge_cache)
                            if annihilator_sign:
                                value = scale * middle_sign * creator_sign * annihilator_sign
                                if i == j:
                                    if creators <= annihilators:
                                        orbit = (creators, annihilators)
                                        bucket = orbits.setdefault(orbit, {})
                                        updated = bucket.get(coordinate, 0) + value
                                        if updated:
                                            bucket[coordinate] = updated
                                        else:
                                            bucket.pop(coordinate, None)
                                else:
                                    if creators == annihilators:
                                        value = value * 2
                                    if creators <= annihilators:
                                        orbit = (creators, annihilators)
                                    else:
                                        orbit = (annihilators, creators)
                                    bucket = orbits.setdefault(orbit, {})
                                    updated = bucket.get(coordinate, 0) + value
                                    if updated:
                                        bucket[coordinate] = updated
                                    else:
                                        bucket.pop(coordinate, None)
    result = {}
    for blocks, bucket in orbits.items():
        if bucket:
            creators, annihilators = blocks
            word = tuple((1, mode) for mode in creators) + tuple((0, mode) for mode in annihilators)
            result[word] = bucket
            if creators != annihilators:
                transpose = tuple((1, mode) for mode in annihilators) + tuple((0, mode) for mode in creators)
                result[transpose] = bucket.copy()
    return result

def gramplan(pattern):
    pending = [(pattern, 1)]
    terms = {}
    while pending:
        word, coefficient = pending.pop()
        finished = True
        position = 0
        while position + 1 < len(word):
            leftflag, leftmode = word[position]
            rightflag, rightmode = word[position + 1]
            if leftflag == rightflag and leftmode == rightmode:
                finished = False
                break
            if leftflag < rightflag or (leftflag == rightflag and leftmode > rightmode):
                prefix = word[:position]
                suffix = word[position + 2:]
                swapped = prefix + (word[position + 1], word[position]) + suffix
                pending.append((swapped, -coefficient))
                if leftflag == 0 and rightflag == 1 and leftmode == rightmode:
                    pending.append((prefix + suffix, coefficient))
                finished = False
                break
            position += 1
        if finished:
            creators = tuple(mode for flag, mode in word if flag == 1)
            annihilators = tuple(mode for flag, mode in word if flag == 0)
            if creators == annihilators:
                coefficient = 2 * coefficient
            elif creators > annihilators:
                creators, annihilators = annihilators, creators
            key = (creators, annihilators)
            terms[key] = terms.get(key, 0) + coefficient
    return tuple((coefficient, groups[0], groups[1]) for groups, coefficient in terms.items() if coefficient)


def propose(payload):
    words = payload['words']
    cache = payload['cache']
    adjoints = [tuple((1 - flag, mode) for flag, mode in reversed(word)) for word in words]
    result = {}
    for i in range(len(words)):
        for j in range(i, len(words)):
            labels = {}
            modes = []
            pattern = []
            for flag, mode in adjoints[i] + words[j]:
                if mode in labels:
                    label = labels[mode]
                else:
                    label = len(modes)
                    labels[mode] = label
                    modes.append(mode)
                pattern.append((flag, label))
            key = ('symmetric CAR orbit plan', tuple(pattern))
            if key in cache:
                plan = cache[key]
            else:
                plan = gramplan(key[1])
                cache[key] = plan
            coordinate = (i, j)
            for coefficient, creators, annihilators in plan:
                if i == j:
                    coefficient = coefficient // 2
                if coefficient:
                    if creators == annihilators:
                        ordered = sorted(modes[label] for label in creators)
                        word = tuple((1, mode) for mode in ordered) + tuple((0, mode) for mode in ordered)
                        result.setdefault(word, {})[coordinate] = coefficient
                    else:
                        groups = []
                        for group in (creators, annihilators):
                            ordered = []
                            for label in group:
                                mode = modes[label]
                                position = len(ordered)
                                ordered.append(mode)
                                while position > 0 and ordered[position - 1] > mode:
                                    ordered[position] = ordered[position - 1]
                                    position -= 1
                                    coefficient = -coefficient
                                ordered[position] = mode
                            groups.append(ordered)
                        word = tuple((1, mode) for mode in groups[0]) + tuple((0, mode) for mode in groups[1])
                        transpose = tuple((1, mode) for mode in groups[1]) + tuple((0, mode) for mode in groups[0])
                        result.setdefault(word, {})[coordinate] = coefficient
                        result.setdefault(transpose, {})[coordinate] = coefficient
    return result

def normalize(word, cache):
    if word in cache:
        return cache[word]
    for k in range(len(word) - 1):
        f, m = word[k]
        g, n = word[k + 1]
        if f == g and m == n:
            cache[word] = {}
            return cache[word]
        if f < g or (f == g and m > n):
            swapped = word[:k] + (word[k + 1], word[k]) + word[k + 2:]
            result = {}
            for term, coefficient in normalize(swapped, cache).items():
                result[term] = -coefficient
            if f < g and m == n:
                reduced = word[:k] + word[k + 2:]
                for term, coefficient in normalize(reduced, cache).items():
                    result[term] = result.get(term, 0) + coefficient
            result = {term: coefficient for term, coefficient in result.items() if coefficient}
            cache[word] = result
            return result
    cache[word] = {word: 1}
    return cache[word]


def cross(annihilators, creators, cache):
    key = (annihilators, creators)
    if key in cache:
        return cache[key]
    if not annihilators:
        result = ((creators, (), 1),)
    elif not creators:
        result = (((), annihilators, 1),)
    else:
        last = annihilators[-1]
        prefix = annihilators[:-1]
        sign = 1 - 2 * (len(creators) % 2)
        terms = []
        for c, a, coefficient in cross(prefix, creators, cache):
            terms.append((c, a + (last,), sign * coefficient))
        if last in creators:
            position = creators.index(last)
            reduced = creators[:position] + creators[position + 1:]
            sign = 1 - 2 * (position % 2)
            for c, a, coefficient in cross(prefix, reduced, cache):
                terms.append((c, a, sign * coefficient))
        result = tuple(terms)
    cache[key] = result
    return result


def exterior(left, right, cache):
    if not left:
        return (right, 1)
    if not right:
        return (left, 1)
    key = (left, right)
    if key in cache:
        return cache[key]
    merged = []
    i = 0
    j = 0
    size = len(left)
    sign = 1
    while i < size and j < len(right):
        if left[i] == right[j]:
            cache[key] = ((), 0)
            return cache[key]
        if left[i] < right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            if (size - i) % 2:
                sign = -sign
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    result = (tuple(merged), sign)
    cache[key] = result
    return result


def propose(payload):
    words = payload['words']
    normalization = {}
    compiled = {}
    basis = []
    adjoints = []
    reversal = (1, 1, -1, -1)
    for word in words:
        if word not in compiled:
            terms = []
            reflected = []
            for term, coefficient in normalize(word, normalization).items():
                creators = tuple(mode for flag, mode in term if flag == 1)
                annihilators = tuple(mode for flag, mode in term if flag == 0)
                terms.append((creators, annihilators, coefficient))
                sign = reversal[len(creators)] * reversal[len(annihilators)]
                reflected.append((annihilators, creators, coefficient * sign))
            compiled[word] = (tuple(terms), tuple(reflected))
        terms, reflected = compiled[word]
        basis.append(terms)
        adjoints.append(reflected)
    contractions = {}
    merges = {}
    rows = {}
    for i in range(len(words)):
        for j in range(i, len(words)):
            polynomial = {}
            symmetric = i != j
            for left_c, left_a, left_value in adjoints[i]:
                for right_c, right_a, right_value in basis[j]:
                    scale = left_value * right_value
                    for middle_c, middle_a, middle_value in cross(left_a, right_c, contractions):
                        creators, creator_sign = exterior(left_c, middle_c, merges)
                        if creator_sign:
                            annihilators, annihilator_sign = exterior(middle_a, right_a, merges)
                            if annihilator_sign:
                                coefficient = scale * middle_value * creator_sign * annihilator_sign
                                term = (creators, annihilators)
                                polynomial[term] = polynomial.get(term, 0) + coefficient
                                if symmetric:
                                    reflected = (annihilators, creators)
                                    polynomial[reflected] = polynomial.get(reflected, 0) + coefficient
            coordinate = (i, j)
            for term, coefficient in polynomial.items():
                if coefficient:
                    rows.setdefault(term, {})[coordinate] = coefficient
    result = {}
    for groups, coordinates in rows.items():
        creators, annihilators = groups
        word = tuple((1, mode) for mode in creators) + tuple((0, mode) for mode in annihilators)
        result[word] = coordinates
    return result

