                prefix = word[:position]
                suffix = word[position + 2:]
                swapped = prefix + (word[position + 1], word[position]) + suffix
                pending.append((swapped, -coefficient))
                if leftflag == 0 and rightflag == 1 and leftmode == rightmode:
                    pending.append((prefix + suffix, coefficient))
                finished = False
                break
